Looks like this is an MST problem, not MobX. I tried to convert over to MobX quickly, and with something like this:

```ts
import React, { useContext } from "react";
import "./styles.css";
import { makeAutoObservable, observable } from "mobx";
import { observer } from "mobx-react-lite";

export const AppContext = React.createContext(null);

// Plain MobX store class
class Store {
  item = {
    id: "1",
    name: "initial",
  };

  constructor() {
    makeAutoObservable(this);
  }

  updateItem(newValue) {
    this.item = newValue;
  }
}

// Component without observer
const Comp = ({ item }) => {
  return <div style={{ background: "lightblue" }}>Hello {item?.name}</div>;
};

// Wrapping existing component with observer
const CompLaterObserved = observer(Comp);

// Directly observed component
const CompDirectlyObserved = observer(({ item }) => {
  return <div style={{ background: "lightblue" }}>Hello {item?.name}</div>;
});

// Create store instance outside of component
const store = new Store();

export default observer(function App() {
  return (
    <AppContext.Provider value={store}>
      <button
        onClick={(e) => {
          e.stopPropagation();
          store.updateItem({
            id: Math.round(Math.random() * 100).toString(),
            name: `item${Math.random()}`,
          });
        }}
      >
        Update
      </button>
      {/* To test the other component make sure to comment out the other one */}
      {/* <CompDirectlyObserved item={store.item} /> */}
      <CompLaterObserved item={store.item} />
    </AppContext.Provider>
  );
});
```

