Yup, @filipkis - looks like we have [`setLivelinessChecking`](https://mobx-state-tree.js.org//API/#setlivelinesschecking) available, which you can set to `'ignore'` for now and clean up these warnings. Here's an example:

```js
import React, { useState, useContext } from "react";
import "./styles.css";
import { useLocalObservable, observer } from "mobx-react-lite";
import { types, flow, setLivelinessChecking } from "mobx-state-tree";

setLivelinessChecking("ignore");

export const AppContext = React.createContext(null);

const Item = types.model("Item", {
  id: types.identifier,
  name: types.string,
});

const Root = types
  .model("Root", {
    item: types.maybeNull(Item),
  })
  .actions((self) => ({
    updateItem: flow(function* (newValue) {
      self.item = newValue;
    }),
  }));

const Comp = ({ item }) => {
  return <div style={{ background: "lightblue" }}>Hello {item?.name}</div>;
};

const CompLaterObserved = observer(Comp);

const CompDirectlyObserved = observer(({ item }) => {
  return <div style={{ background: "lightblue" }}>Hello {item?.name}</div>;
});

export default observer(function App() {
  const store = useLocalObservable(() => {
    return Root.create({ item: { id: "1", name: "initial" } });
  });
  return (
    <AppContext.Provider value={store}>
      <button
        onClick={(e) => {
          e.stopPropagation();
          store.updateItem({
            id: Math.round(Math.random() * 100).toString(),
            name: `item${Math.random()}`,
          });
        }}
      >
        Update
      </button>
      {/* To test the other component make sure the comment out the other one */}
      {/* <CompDirectlyObserved item={store.item} /> */}
      <CompLaterObserved item={store.item} />
    </AppContext.Provider>
  );
});
```

And [CodeSandbox](https://codesandbox.io/p/devbox/mst-component-params-demo-forked-r7wjcr?file=%2Fsrc%2FApp.jsx%3A58%2C1&workspaceId=ws_QGa4cGacuoY7BgaNFKGDj8).

This is a global setting, so you can't just do it on those particular models. I'll ask around other maintainers and see if we want to do something else there, but this is a pretty built-in way to avoid the problems you're experiencing.

